<?php
namespace App\Domain\ApiHub\Models;use Illuminate\Database\Eloquent\Model;use Illuminate\Support\Facades\Crypt;use Illuminate\Support\Str;
final class TenantApiWebhookEndpoint extends Model{public const EVENTS=['shipment.created','shipment.ready_for_pickup','shipment.picked_up','shipment.in_transit','shipment.out_for_delivery','shipment.delivery_failed','shipment.delivered'];protected $fillable=['tenant_id','api_client_id','name','url','events','status','secret_encrypted','secret_prefix','last_delivery_at'];protected $hidden=['secret_encrypted'];protected $casts=['events'=>'array','last_delivery_at'=>'datetime'];protected static function booted():void{self::creating(fn(self$m)=>$m->uuid??=(string)Str::uuid());}public function secret():string{return Crypt::decryptString($this->secret_encrypted);}public function client(){return$this->belongsTo(TenantApiClient::class,'api_client_id');}}
